/**
 * Monotonic broker/client contract revision. Revision 0 is the overlap baseline for clients built
 * before negotiation shipped; revision 1 is the first explicit handshake. Revision 2 adds
 * reason-tagged Drive arbitration and structured attach conflicts. Revision 3 adds durable,
 * versioned shared composer drafts. Revision 4 adds the optional Attention session-title
 * snapshot and exact-revision bulk dismissal route. Revision 5 adds bounded
 * backward transcript paging errors plus an optional append-aware native
 * history source identity. Revision 6 separates transient native-source churn
 * from terminal paging limits with HISTORY_PAGE_SOURCE_CHANGED and adds
 * optional structured interruption/history-reset semantics. Revision 7 adds
 * bounded inline prompt files plus credential/tool/session-bound staged
 * attachment references and honest attachment ACK/NACK behavior. Revision 8 adds
 * pre-session model catalogs and exact optional model selection for immediate
 * and scheduled creation. Revision 9 adds the optional normalized
 * {@link ToolSemantic} envelope on `tool-call`/`tool-result` so command,
 * file-read, search, and web families present structurally instead of by native
 * tool name. Revision 10 adds four optional structural additions for bounded
 * large-history replay (H1c): `bodyTruncated` on `model-output`/`thinking`/
 * `user-message`, marking a body the broker shortened so an over-contract
 * history could still be replayed; {@link HistorySnapshotSink.readsBoundedTailOnly},
 * letting a sink declare that it retains only a bounded newest window so an
 * adapter may relax the ceilings that existed solely to bound retention; and
 * {@link HistorySnapshotCapture.skippedRecords}, reporting records an adapter
 * passed over because no bounded window could hold them; and
 * {@link HistorySnapshotSink.suppressStateAuthority}, which an adapter calls
 * after settling accepted messages when it skipped a native record, so the
 * sink stops asserting latest-wins state it can no longer prove is current.
 * The registry-derived {@link BROKER_CONTRACT_SURFACE_HASH} does not move for
 * any of them: none adds a route, frame kind, message type or error code, which is
 * exactly why the revision must: a structural DTO change is reviewable only if
 * it is numbered. All revision-5 through revision-10 additions are backward
 * compatible, so the client minimum does not move. Raise the minimum only
 * after every supported store client has crossed the corresponding revision.
 */
export const BROKER_CONTRACT_REVISION = 10 as const;
export const BROKER_MINIMUM_CLIENT_CONTRACT_REVISION = 0 as const;
export const BROKER_CONTRACT_OVERLAP_REVISIONS = 1 as const;

/**
 * Oldest broker contract the generated first-party client identity will drive. Revision 2
 * introduced reason-tagged Drive arbitration and structured attach conflicts; a client built to
 * restore Drive through them cannot safely drive a revision-1 broker that silently ignores the
 * reason, so the new client fails closed there. Compatibility is deliberately asymmetric: older
 * clients remain accepted by this broker through BROKER_MINIMUM_CLIENT_CONTRACT_REVISION and the
 * overlap window above.
 */
export const CLIENT_MINIMUM_BROKER_CONTRACT_REVISION = 2 as const;

function fnv1a32(value: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

/** Deterministic identity for the enumerated route, frame, message, and error registries.
 * Structural DTO changes still require an explicit revision change and snapshot review. */
export const BROKER_CONTRACT_SURFACE_HASH = `fnv1a32:${fnv1a32(JSON.stringify({
  product: PRODUCT_IDENTITY,
  routes: BROKER_ROUTES,
  errorCodes: BROKER_ERROR_CODES,
  wireFrameKinds: BROKER_WIRE_FRAME_KINDS,
  clientMessageKinds: BROKER_CLIENT_MESSAGE_KINDS,
  messageTypes: CANONICAL_MESSAGE_TYPES,
  compatibility: { overlapRevisions: BROKER_CONTRACT_OVERLAP_REVISIONS },
}))}` as const;

export interface BrokerContractIdentity {
  revision: number;
  minimumClientRevision: number;
  surfaceHash: string;
}

export interface ClientContractIdentity {
  revision: number;
  /** Oldest broker contract this client can safely use. */
  minimumBrokerRevision: number;
  /** Optional until every client build exports the deterministic registry hash. */
  surfaceHash?: string;
}

export type BrokerClientCompatibilityStatus =
  | 'compatible'
  | 'client-behind'
  | 'broker-behind'
  | 'hard-incompatible'
  | 'unknown';

export interface BrokerClientCompatibility {
  status: BrokerClientCompatibilityStatus;
  readOnly: boolean;
  reason: string;
  broker: BrokerContractIdentity;
  client?: ClientContractIdentity;
}

export const BROKER_CONTRACT: Readonly<BrokerContractIdentity> = Object.freeze({
  revision: BROKER_CONTRACT_REVISION,
  minimumClientRevision: BROKER_MINIMUM_CLIENT_CONTRACT_REVISION,
  surfaceHash: BROKER_CONTRACT_SURFACE_HASH,
});

/** Pure compatibility matrix shared by broker tests and generated client contract snapshots. */
export function evaluateBrokerClientCompatibility(
  client?: Readonly<ClientContractIdentity>,
  broker: Readonly<BrokerContractIdentity> = BROKER_CONTRACT,
): BrokerClientCompatibility {
  if (!client) {
    return {
      status: 'unknown',
      readOnly: false,
      reason: 'client did not advertise a contract revision',
      broker: { ...broker },
    };
  }
  const valid = [client.revision, client.minimumBrokerRevision, broker.revision, broker.minimumClientRevision]
    .every((value) => Number.isSafeInteger(value) && value >= 0);
  if (!valid || client.minimumBrokerRevision > client.revision
      || broker.minimumClientRevision > broker.revision) {
    return {
      status: 'hard-incompatible',
      readOnly: true,
      reason: 'contract revision metadata is invalid',
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (client.revision < broker.minimumClientRevision) {
    return {
      status: 'hard-incompatible',
      readOnly: true,
      reason: `client contract ${client.revision} is older than broker minimum ${broker.minimumClientRevision}`,
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (broker.revision < client.minimumBrokerRevision) {
    return {
      status: 'hard-incompatible',
      readOnly: true,
      reason: `broker contract ${broker.revision} is older than client minimum ${client.minimumBrokerRevision}`,
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (client.revision === broker.revision
      && client.surfaceHash && client.surfaceHash !== broker.surfaceHash) {
    return {
      status: 'hard-incompatible',
      readOnly: true,
      reason: 'equal contract revisions advertise different public surfaces',
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (Math.abs(client.revision - broker.revision) > BROKER_CONTRACT_OVERLAP_REVISIONS) {
    return {
      status: 'hard-incompatible',
      readOnly: true,
      reason: `contract revisions differ by more than the ${BROKER_CONTRACT_OVERLAP_REVISIONS}-revision overlap window`,
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (client.revision < broker.revision) {
    return {
      status: 'client-behind',
      readOnly: false,
      reason: `client contract ${client.revision} is behind broker contract ${broker.revision}`,
      broker: { ...broker },
      client: { ...client },
    };
  }
  if (client.revision > broker.revision) {
    return {
      status: 'broker-behind',
      readOnly: false,
      reason: `broker contract ${broker.revision} is behind client contract ${client.revision}`,
      broker: { ...broker },
      client: { ...client },
    };
  }
  return {
    status: 'compatible',
    readOnly: false,
    reason: 'broker and client contract revisions match',
    broker: { ...broker },
    client: { ...client },
  };
}

