type _MsgType = AgentMessage['type'];
type _Listed = (typeof CANONICAL_MESSAGE_TYPES)[number];
// If a union member is missing from the list, this type is a tuple literal and `true` won't assign.
const _coversUnion: [_MsgType] extends [_Listed] ? true : ['MISSING from CANONICAL_MESSAGE_TYPES', Exclude<_MsgType, _Listed>] = true;
// If the list has an entry that isn't a real union member (typo/removed variant), same failure.
const _noExtra: [_Listed] extends [_MsgType] ? true : ['EXTRA in CANONICAL_MESSAGE_TYPES', Exclude<_Listed, _MsgType>] = true;
void _coversUnion;
void _noExtra;

export type AgentMessageHandler = (message: AgentMessage) => void;

/** A slash command the UI can offer. `action` = a quick tool operation; `prompt` = starts a turn. */
export interface SlashCommand {
  name: string;
  description?: string;
  kind: 'action' | 'prompt';
}

/** Per-command turn overrides. Prompt-like slash commands (templates/skills) must honor the same
 *  model and permission-mode selectors as ordinary prompts; action commands may ignore them. */
export type CommandInput = Pick<PromptInput, 'model' | 'agent' | 'permissionMode'>;

/**
 * Result of running a slash command. A `notice` is short, requester-facing feedback
 * (e.g. "Reverted the last message") that the UI shows as a system line — distinct from
 * an error, so a successful action never looks like a failure. Returning nothing is fine
 * for commands whose effect streams back as normal session messages.
 */
export interface CommandResult {
  notice?: string;
}

/** Unsubscribe a handler registered with {@link SessionConnection.subscribe}. */
export type Unsubscribe = () => void;

/** Optional history replay request. Adapters may ignore this until they implement native deltas. */
export interface HistoryQuery {
  /** Adapter/broker-issued cursor. When supported, return only durable messages after this point. */
  since?: string;
  /** New clients can request artifact metadata references instead of inline bytes. */
  artifactMode?: 'inline' | 'reference';
}

// ── Capabilities ─────────────────────────────────────────────────────────────

export interface AgentCapabilities {
  integrationKind: IntegrationKind;
  /** Supported attach modes, best-first. */
  attachModes: AttachMode[];
  supportsObserve: boolean;
  supportsResume: boolean;
  supportsLiveAttach: boolean;
  /** Agent has a native "send file to user" signal (vs filesystem-detect only). */
  supportsNativeArtifact: boolean;
  /** Accepts native binary/image input (vs path-reference fallback only). */
  supportsNativeFileInput: boolean;
  supportsModelSwitch: boolean;
  permissionGranularity: PermissionGranularity;
}

/** Freshness state for a broker-managed long-lived agent runtime (daemon/serve).
 * Version drift is non-outage: automatic restart is allowed only when `autoRestartReady` is true;
 * otherwise clients surface the pending update and an explicitly-confirmed manual action. */
export interface AgentRuntimeUpdateStatus {
  agent: string;
  displayName: string;
  runtimeKind?: string;
  /** Provider-supplied consequence shown before a maintainer forces a restart. */
  restartWarning?: string;
  managed: boolean;
  state: 'current' | 'pending' | 'unavailable' | 'error';
  updateAvailable: boolean;
  autoRestartReady: boolean;
  /** Native freshness causes that require the managed runtime to restart. Additive for forwards
   * compatibility; absent older payloads mean binary drift when versions differ. */
  pendingChanges?: Array<'binary-version' | 'configuration'>;
  installedVersion?: string;
  runningVersion?: string;
  blockers?: number;
  blockerComposition?: {
    idle: number;
    working: number;
    needsInput: number;
    unknown: number;
  };
  blockerDetails?: Array<{
    id: string;
    status: 'idle' | 'working' | 'needs-input' | 'unknown';
    detail?: string;
  }>;
  detail?: string;
  checkedAt: number;
}

export type CodexRuntimeUpdatePolicy = 'when-detached' | 'when-idle';

export type DriveState = 'observing' | 'driving' | 'unavailable' | 'unknown';

export interface SessionDriveControl {
  state: DriveState;
  supported: boolean;
  reason?: string;
  /** A live terminal currently owns this session, so driving now will CONTINUE IN A FORK (new uuid)
   *  for single-owner safety. The app must warn before the first driven prompt: quitting the terminal
   *  first keeps the SAME session instead. */
  willFork?: boolean;
}

export interface SessionTerminalSync {
  /** Sync infra exists for this tool/session at all (vs structurally impossible — e.g. a 3rd-party
   *  Claude wrapper). Feeds {@link canMutateSession} together with {@link active}; kept additively
   *  alongside {@link syncAvailable} (D8) so the broker can still distinguish can-never-sync sessions
   *  (→ Take-over fallback) from sync-available-but-not-active ones. */
  supported: boolean;
  /**
   * Explicit, per-adapter, roster-time signal: this session COULD be synced now or via one in-app
   * setup step (OpenCode `serve` reachable, Codex daemon enabled, Pi bridge extension installed). It is
   * **set by the adapter from real reachability** — NOT derived in the UI and NOT inferred from
   * {@link supported} or the tool name (D6/D7). Invariant: `active ⟹ syncAvailable ⟹ supported`. The UI
   * shows the "sync available" affordance only when `syncAvailable && !active`; `active` shows "Synced".
   * Governing contract: docs/architecture/client-ui.md
   */
  syncAvailable: boolean;
  /** OUR channel/daemon/bridge socket is connected for THIS session right now — the only fact that
   *  flips the mutation gate. Requires per-session proof (a socket file, a daemon-loaded thread, a
   *  bridge `hello`), never a mere capability. */
  active: boolean;
  label?: string;
  command?: string;
  note?: string;
  reason?: string;
  /** What an actively-synced session accepts FROM the app. 'full' (default): prompts AND answers — the
   *  bridge can inject a live turn (e.g. Pi). 'answer-only': permission/question answers ONLY, no new-prompt
   *  inject (e.g. Claude hooks — there is no live-inject path, so the composer stays read-only while the
   *  permission/question cards remain actionable). Absent ⇒ 'full'. */
  input?: 'full' | 'answer-only';
  /**
   * Additive presence/ownership signals:
   *  If present and `active === true`, then `presence` must be `shared`.
   */
  presence?: SessionTerminalPresence;
  /**
   * Ownership hint:
   *  - `join`: a shared terminal is added while the app remains connected;
   *  - `handoff`: terminal ownership is handed off and app ownership is relinquished.
   */
  action?: SessionTerminalAction;
  /** `behind` means a proven private terminal missed an accepted app-side mutation. */
  behind?: boolean;
}

export interface SessionControlState {
  drive: SessionDriveControl;
  terminalSync: SessionTerminalSync;
}

// ── Sessions ─────────────────────────────────────────────────────────────────

export interface SessionInfo {
  /** Stable session id within the tool. */
  id: string;
  /** Stable conversation lineage id across native forks/continues when an adapter can provide one. */
  lineageId?: string;
  /** The uuid the LIVE driven conversation currently writes under when it differs from `id` (a
   *  single-owner-safety fork). Terminal-resume hints must cite THIS uuid or they point at a
   *  transcript missing the driven turns. */
  liveUuid?: string;
  /** Backend id, e.g. 'opencode' | 'pi'. */
  tool: string;
  /** Set by the broker (machine/tailnet name); undefined locally. */
  machine?: string;
  title: string;
  slug?: string;
  cwd?: string;
  /** User-facing broker/project alias for this cwd group. Does not rename or move the real directory. */
  projectName?: string;
  /**
   * How this session came to exist, when it was NOT directly human-initiated (omitted = a normal
   * user-started session). `'subagent'` = spawned by a parent session (see {@link parentThreadId});
   * `'exec'` = automated/non-interactive runs (`codex exec`, agent-driven spawns, probe harnesses);
   * `'vscode'` = an IDE-extension session (human, but surfaced separately so clients can filter).
   * Clients hide `subagent`/`exec` by default — "hide auto sessions, show human-initiated ones".
   */
  origin?: 'subagent' | 'exec' | 'vscode';
  /** For origin 'subagent': the native id of the session that spawned this one (roster linkage). */
  parentThreadId?: string;
  /** The tool's OWN session/thread id when {@link id} is an encoded handle (e.g. codex ids are the
   *  base64url rollout path). Lets clients resolve {@link parentThreadId} → the parent's roster row. */
  nativeId?: string;
  /**
   * What the agent is doing right now (activity), independent of how you connect (that's
   * {@link attachMode}). `working` = a turn is actively running; `needs-input` = blocked on the
   * user (a pending permission/approval or interactive question — surface as a to-do);
   * `idle` = available, nothing running (merges the old idle + historical).
   */
  status: 'working' | 'needs-input' | 'idle';
  /**
   * Provenance of how this session was launched/created (e.g. app, terminal, IDE), separate from
   * capabilities that arrive only for active terminal sync sessions.
   */
  launchSurface?: SessionLaunchSurface;
  /** Best attach mode available for THIS session right now. */
  attachMode: AttachMode;
  model?: string;
  /** Current model (provider + id), for preselecting the model picker. */
  currentModel?: { providerID: string; modelID: string; label?: string; reasoningEffort?: string; variant?: string };
  /** Current agent/mode (e.g. 'build'), for preselecting the agent picker. */
  currentAgent?: string;
  /** Current permission mode, for preselecting the mode picker. */
  currentMode?: string;
  createdAt?: number;
  updatedAt?: number;
  /**
   * Optional adapter-provided instruction for mirroring this session live in the tool's own
   * terminal UI (the single-owner sync model). The UI renders it generically when present —
   * no per-tool conditionals. e.g. OpenCode supplies an `opencode attach …` command.
   */
  terminalSyncHint?: { label: string; command: string; note?: string };
  /** Explicit Observe+Drive and True Sync state. New UI should prefer this over attachMode. */
  control?: SessionControlState;
}

/**
 * An open connection to one session. The broker holds at most one of these per
 * (tool, session) — it is the single owner — and fans messages out to N clients.
 */
export interface SessionConnection {
  readonly info: SessionInfo;
  /** Replay prior conversation (history) as normalized messages. */
  getHistory(query?: HistoryQuery): Promise<AgentMessage[]>;
  /**
   * Read bounded current-state overlays that are not part of the native
   * transcript cursor (for example, Codex's live goal state).
   *
   * Compact history attach calls this separately so current state remains
   * authoritative without materializing the complete transcript.
   */
  getHistoryOverlays?(query?: HistoryQuery): Promise<AgentMessage[]>;
  /**
   * Cheap revision for the native source read by {@link getHistory}.
   *
   * `sourceId` changes when the backing source is replaced. `revision` changes
   * for every content change. Adapters may expose a monotone `appendPosition`
   * and stable `rewriteToken`; the broker can then keep serving an immutable
   * paging snapshot while the same source only appends. A shrink, replacement,
   * rewrite-token change, or non-monotone position fails closed.
   *
   * When unavailable, truncated backward paging fails closed instead of
   * repeatedly rereading an unbounded source or reusing a stale index.
   */
  getHistorySourceIdentity?():
    | Promise<HistorySourceIdentity | undefined>
    | HistorySourceIdentity
    | undefined;
  /**
   * Stream one history read into [sink], and return the identity of the SAME immutable prefix.
   *
   * {@link getHistory} and {@link getHistorySourceIdentity} are two separate observations of a
   * source that may be growing between them, so pairing their results is only ever a guess: an
   * ordinary append during the read makes the identity describe bytes the messages do not contain.
   * The broker cannot tell that apart from a rewrite, so it used to fail the page closed and mark
   * the connection unpageable — a normal Codex append could poison paging for the whole socket.
   *
   * An adapter that can capture a byte/row boundary once reads exactly through that boundary and
   * emits what is inside it, so later appends stay compatible with the snapshot while a rewrite,
   * compaction, or shrink still fails closed.
   *
   * The messages go to [sink] rather than into a returned array so the receiver's budget applies
   * DURING the read: `accept` returning false means stop reading and return a refusal. Adapters
   * that cannot capture a boundary omit the method; the broker then falls back to the two-probe
   * read and treats a source change as retriable rather than terminal.
   */
  captureHistorySnapshot?(sink: HistorySnapshotSink, query?: HistoryQuery):
    | Promise<HistorySnapshotCapture | HistorySnapshotRefusal | undefined>
    | HistorySnapshotCapture
    | HistorySnapshotRefusal
    | undefined;
  /** Subscribe to live messages; returns an unsubscribe fn. */
  subscribe(handler: AgentMessageHandler): Unsubscribe;
  /** Mutating input. The broker may call this only when `info.control` proves Drive ownership or
   *  active True Sync; Observe connections must reject or ignore it. */
  sendPrompt(input: PromptInput): Promise<void>;
  /** Mutating approval response; same ownership precondition as {@link sendPrompt}. */
  respondPermission(requestId: string, decision: PermissionDecision): Promise<void>;
  /** Answer a `question-request`. `answers` is one array of selected labels per question
   *  (custom free-text answers are passed as a label). Distinct from sending a prompt. Mutating; same
   *  ownership precondition as {@link sendPrompt}. */
  answerQuestion?(requestId: string, answers: string[][]): Promise<void>;
  /** Dismiss a `question-request` without answering. Mutating; same ownership precondition. */
  rejectQuestion?(requestId: string): Promise<void>;
  /** Deliver a user-uploaded file to the agent (native input or path-reference). Mutating. */
  sendFile?(file: FileInput): Promise<void>;
  /** Slash commands available for this session (built-in actions + tool/template commands). */
  listCommands?(): Promise<SlashCommand[]>;
  /** Models selectable for this session (for the model picker). */
  listModels?(): Promise<ModelOption[]>;
  /** Agents/modes selectable for this session, e.g. build/plan (for the agent picker). */
  listAgents?(): Promise<AgentOption[]>;
  /** Switch the session's active agent/mode (e.g. build → plan) so SUBSEQUENT turns run under it,
   *  without starting a turn. Only names the adapter advertised via {@link listAgents} are valid —
   *  the broker validates before calling. Mutating; same ownership precondition as
   *  {@link sendPrompt}. Adapters that can observe a native switch (e.g. from the tool's own TUI)
   *  reflect it back via a `metadata-update` with key `sessionInfo` and value `{currentAgent}`. */
  setAgent?(agent: string): Promise<void>;
  /** Permission/approval modes selectable for this session (for the mode picker). */
  listModes?(): Promise<ModeOption[]>;
  /** Currently-pending permission/question requests, replayed AFTER history on attach so a client
   *  joining an already-blocked session sees the box (not just the needs-input badge). The UI dedupes
   *  by requestId, so this is idempotent across reattach/resync. */
  getPending?(): Promise<AgentMessage[]> | AgentMessage[];
  /** Run a slash command (built-in action → its endpoint; otherwise a turn-starting command). Mutating.
   *  May return a {@link CommandResult} with a `notice` for requester-facing feedback. */
  runCommand?(name: string, args?: string, input?: CommandInput): Promise<CommandResult | void>;
  /** Semantic plan lifecycle action from the app. Adapters may map this to a native plan-control
   *  channel; the broker has an explicit prompt fallback for adapters that only support text steering. */
  respondPlan?(input: PlanActionInput): Promise<void>;
  close(): Promise<void>;
}

/** Bounded source probe used to validate one immutable history-page snapshot. */
export interface HistorySourceIdentity {
  /** Stable identity of the backing file/database/live history owner. */
  sourceId: string;
  /** Exact current source revision. */
  revision: string;
  /** Optional monotone append boundary (bytes, rows, or adapter generation). */
  appendPosition?: number;
  /** Optional token that changes on compaction, revert, or prefix rewrite. */
  rewriteToken?: string;
}

/**
 * The consumer a capture writes into, one message at a time.
 *
 * The receiver — the broker's paging cache — owns the only budget that matters, so it is the one
 * that decides when a capture has produced enough. Handing back a complete `AgentMessage[]` instead
 * meant the adapter had to build the whole transcript (and, file-backed, every parsed record behind
 * it) before any limit could run: the limits bounded what was retained, not what was constructed.
 */
export interface HistorySnapshotSink {
  /**
   * Opt in to compact native locations.
   *
   * A sink that sets this flag does not retain complete encoded messages. The
   * adapter must pass a non-negative safe-integer location for every accepted
   * message and return a matching {@link HistorySnapshotPageReader} with the
   * capture. Sinks without this flag keep the revision-6 streaming contract.
   */
  readonly acceptsLocations?: boolean;
  /**
   * Declare that this sink retains only a bounded newest window.
   *
   * Such a sink cannot overflow — it evicts — and that changes which of the
   * adapter's own ceilings still mean anything. A whole-source byte cap, a
   * per-record cap, and an enrichment cap exist so that INDEXING a source
   * cannot become unbounded work. A sink that keeps a fixed window makes the
   * read O(window) in memory whatever the source size, so refusing it outright
   * leaves a client with no history at all where a degraded one was available.
   *
   * An adapter honouring this flag must still bound the read; it may relax
   * exactly those ceilings whose only justification was bounding retention, and
   * should skip or evict rather than refuse wherever it can. Everything else —
   * one immutable prefix, identity, rewrite and compaction detection — is
   * unchanged, so the cursors such a read issues remain genuine.
   */
  readonly readsBoundedTailOnly?: boolean;
  /**
   * Take the next message of the captured prefix, in native order.
   *
   * Returns false when the receiver's budget is exhausted. The adapter must then stop reading and
   * return a {@link HistorySnapshotRefusal}; nothing already accepted is usable.
   */
  accept(message: AgentMessage, location?: number): boolean;
  /**
   * Give up every latest-wins state claim, because part of the source was not read.
   *
   * An adapter that skipped a record (see {@link HistorySnapshotCapture.skippedRecords}) MUST call
   * this after its final accepted message and before the capture returns. A skipped record never
   * reaches {@link accept}, so a newer
   * `task-list-state` / `goal-state` / `metadata-update` inside it cannot supersede the older value
   * the sink already holds — and that older value would then be replayed as CURRENT. The sink
   * cannot know which keys the unread bytes touched, so it fails closed on all of them.
   *
   * Only latest-wins STATE is affected. Transcript rows are positional and their absence is already
   * reported honestly by the skip count. Optional so a sink that retains no state can omit it;
   * calling it more than once is idempotent.
   */
  suppressStateAuthority?(): void;
}

/** Result of resolving compact native locations from one immutable prefix. */
export interface HistorySnapshotPageRead {
  /** Identity of the prefix the locations belong to. */
  identity: HistorySourceIdentity;
  /** Exactly one normalized message per requested location, in request order. */
  messages: AgentMessage[];
  /** Optional bounded-work evidence for deterministic adapter tests. */
  work?: {
    recordsRead: number;
    bytesRead: number;
  };
}

/**
 * Adapter-owned random-access reader paired with a compact history index.
 *
 * `retainedBytes` includes every offset, descriptor, and enrichment lookup the
 * reader keeps after construction. It excludes the native source itself.
 */
export interface HistorySnapshotPageReader {
  readonly retainedBytes: number;
  read(
    locations: readonly number[],
    query?: HistoryQuery,
  ):
    | Promise<HistorySnapshotPageRead | HistorySnapshotRefusal | undefined>
    | HistorySnapshotPageRead
    | HistorySnapshotRefusal
    | undefined;
}

/** Identity of the exact prefix a capture wrote into the sink. */
export interface HistorySnapshotCapture {
  /** Identity of the captured prefix — never of a later state of the source. */
  identity: HistorySourceIdentity;
  /** Present only when the sink opted into compact native locations. */
  reader?: HistorySnapshotPageReader;
  /**
   * Records inside the captured prefix that were passed over unread.
   *
   * Only a {@link HistorySnapshotSink.readsBoundedTailOnly} sink can produce a non-zero count: an
   * adapter may skip a record too large for a bounded window rather than refuse the whole source.
   * Reported so the broker's gap notice can say the window is the newest READABLE messages instead
   * of implying it is the newest messages — the skip is silent otherwise, and a silently incomplete
   * window is exactly the kind of claim this path exists to avoid. Absent means nothing was skipped.
   */
  skippedRecords?: number;
}

/**
 * An adapter's typed refusal to capture, distinct from "the source moved".
 *
 * A source that overflows a stated bound will overflow it again on the next request, so the broker
 * must report it as a resource limit rather than as something a retry can fix. Returning
 * `undefined` still means "could not read it this time" and stays retriable.
 */
export interface HistorySnapshotRefusal {
  refusal: 'resource-limit';
}

/** Whether an adapter answered a capture request with a typed refusal. */
export function isHistorySnapshotRefusal(
  value: HistorySnapshotCapture | HistorySnapshotRefusal | undefined,
): value is HistorySnapshotRefusal {
  return !!value && 'refusal' in value;
}
